var NAAM_STD='Crisna se Kombuis';
function isStdNaam(n){ return String(n||'').trim().toLowerCase()===NAAM_STD.toLowerCase(); }
function kopNaam(b){ return isStdNaam(b.naam)
  ? '<h1 class="merkkop">'+logoSvg('var(--ink)','var(--merk)','logo')+'</h1>'
  : '<h1>'+h(b.naam)+'</h1>'; }
function logoSvg(ink,acc,klas){
  return '<svg class="'+klas+'" viewBox="'+LOGO.vb.join(' ')+'" role="img" aria-label="'+NAAM_STD+'" focusable="false">'
    + '<path style="fill:'+ink+'" d="'+LOGO.ink+'"/><path style="fill:'+acc+'" d="'+LOGO.acc+'"/></svg>';
}
function ikoonSvg(bg,fg,klas){
  return '<svg class="'+klas+'" viewBox="0 0 340 340" aria-hidden="true" focusable="false">'
    + '<circle cx="170" cy="170" r="170" style="fill:'+bg+'"/><path style="fill:'+fg+'" d="'+LOGO.C+'"/>'
    + '<g style="fill:'+fg+'" transform="translate(115 '+LOGO.lepelY+') scale(0.982 1)">'
    + '<ellipse cx="20" cy="13" rx="18" ry="10"/><rect x="34" y="10" width="76" height="6" rx="3"/></g></svg>';
}
/* teken 'n absolute M/L/C/Z-pad in die PDF (mm) */
function pdfPad(doc,d,x0,y0,sk,vx,vy){
  var t=d.match(/[MLCZ]|-?\d*\.?\d+/g), ops=[], i=0, c;
  function X(v){return x0+(+v-vx)*sk;} function Y(v){return y0+(+v-vy)*sk;}
  while(i<t.length){
    c=t[i++];
    if(c==='M'){ops.push({op:'m',c:[X(t[i]),Y(t[i+1])]});i+=2;}
    else if(c==='L'){ops.push({op:'l',c:[X(t[i]),Y(t[i+1])]});i+=2;}
    else if(c==='C'){ops.push({op:'c',c:[X(t[i]),Y(t[i+1]),X(t[i+2]),Y(t[i+3]),X(t[i+4]),Y(t[i+5])]});i+=6;}
    else if(c==='Z'){ops.push({op:'h',c:[]});}
  }
  doc.path(ops); doc.fill();
}
function pdfLogo(doc,x,bo,hoogte){
  var sk=hoogte/LOGO.vb[3];
  doc.setFillColor(42,27,20); pdfPad(doc,LOGO.ink,x,bo,sk,LOGO.vb[0],LOGO.vb[1]);
  doc.setFillColor(142,59,36); pdfPad(doc,LOGO.acc,x,bo,sk,LOGO.vb[0],LOGO.vb[1]);
  return LOGO.vb[2]*sk;
}
function pdfIkoon(doc,x,bo,grootte){
  var sk=grootte/340, ly=LOGO.lepelY;
  doc.setFillColor(142,59,36); doc.circle(x+170*sk, bo+170*sk, 170*sk, 'F');
  doc.setFillColor(245,237,224); pdfPad(doc,LOGO.C,x,bo,sk,0,0);
  doc.ellipse(x+(115+20*0.982)*sk, bo+(ly+13)*sk, 18*0.982*sk, 10*sk, 'F');
  doc.roundedRect(x+(115+34*0.982)*sk, bo+(ly+10)*sk, 76*0.982*sk, 6*sk, 3*sk, 3*sk, 'F');
}
/* ============ berging ============ */
var SLEUTEL='crisna_kombuis_v1';
var S=null, laasteOntdoen=null, toastTyd=null;

function vandagISO(){var d=new Date();return isoVan(d);}
function isoVan(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
function pad(n){return (n<10?'0':'')+n;}
function id(){return Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);}

function saadjie(){
  var etes=['08-03','08-04','08-05','08-06','08-07','08-08','08-09','08-12','08-13','08-14',
            '08-16','08-17','08-18','08-19','08-20','08-21','08-22','08-24','08-25','08-26','08-28'];
  function E(dag,bedrag){return {id:id(),tipe:'item',beskr:'Ete',bedrag:bedrag||15,datum:'2026-'+dag};}
  function B(dag,bedrag){return {id:id(),tipe:'item',beskr:'Biltong',bedrag:bedrag,datum:dag?'2026-'+dag:'2026-08-15'};}
  function P(dag,bedrag){return {id:id(),tipe:'betaling',beskr:'Betaling',bedrag:bedrag,datum:'2026-'+dag};}

  var nathan=[];
  ['08-03','08-04','08-05','08-06','08-07','08-08','08-09'].forEach(function(d){nathan.push(E(d));});
  nathan.push(B('08-11',30));
  ['08-12','08-13','08-14','08-16','08-17','08-18','08-19'].forEach(function(d){nathan.push(E(d));});
  nathan.push(E('08-20',20)); nathan.push(E('08-21',15)); nathan.push(B('08-21',150));
  nathan.push(E('08-22',17)); nathan.push(E('08-24')); nathan.push(E('08-25'));
  nathan.push(B('08-25',30)); nathan.push(E('08-26')); nathan.push(B('08-28',30));
  nathan.push(P('08-28',160));

  var derek=[];
  ['08-03','08-04','08-05','08-06','08-07','08-08','08-09','08-12','08-13','08-14'].forEach(function(d){derek.push(E(d));});
  derek.push({id:id(),tipe:'item',beskr:'Biltong',bedrag:30,datum:'2026-07-27'});
  ['08-16','08-17','08-18','08-19','08-20','08-21','08-22','08-24','08-25','08-26','08-28'].forEach(function(d){derek.push(E(d));});
  derek.push(P('08-28',500));

  var chris=[];
  etes.forEach(function(d){chris.push(E(d));});
  chris.push(B('08-26',60)); chris.push(P('08-28',340));

  return {
    v:1,
    besigheid:{naam:'Crisna se Kombuis',slag:'Tuisgemaakte etes & biltong',eienaar:'Crisna',geld:'$'},
    items:[{id:id(),naam:'Ete',prys:15},{id:id(),naam:'Biltong',prys:30}],
    klante:[
      {id:id(),naam:'Nathan',open:133,inskrywings:nathan,laasteStaat:null},
      {id:id(),naam:'Derek', open:200,inskrywings:derek, laasteStaat:null},
      {id:id(),naam:'Chris', open:30, inskrywings:chris, laasteStaat:null}
    ]
  };
}
function laai(){
  var r=null;
  try{r=localStorage.getItem(SLEUTEL); if(r){S=JSON.parse(r); migreer(); return;}}
  catch(e){ try{ if(r) localStorage.setItem(SLEUTEL+'_stukkend',r); }catch(e2){} }
  S=saadjie(); migreer(); stoor();
}
function stoor(){ try{localStorage.setItem(SLEUTEL,JSON.stringify(S));}catch(e){} if(window.wolk) wolk.gestoor(); }
function kiekie(){ return JSON.stringify(S); }
function herstelKiekie(k){ S=JSON.parse(k); migreer(); stoor(); teken(); }

/* ============ berekening ============ */
function G(n){var t=S.besigheid.geld||'$';var neg=n<0;n=Math.abs(n);
  return (neg?'-':'')+t+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
var MAANDE=['Jan','Feb','Mrt','Apr','Mei','Jun','Jul','Aug','Sep','Okt','Nov','Des'];
var MAANDVOL=['Januarie','Februarie','Maart','April','Mei','Junie','Julie','Augustus','September','Oktober','November','Desember'];
function dKort(iso){if(!iso)return '';var p=iso.split('-');return (+p[2])+' '+MAANDE[+p[1]-1];}
function dVol(iso){if(!iso)return '';var p=iso.split('-');return (+p[2])+' '+MAANDE[+p[1]-1]+' '+p[0];}
function tekenVan(e){return e.tipe==='betaling'? -e.bedrag : e.bedrag;}
function saldo(k){var s=k.open||0;k.inskrywings.forEach(function(e){s+=tekenVan(e);});return s;}
function totaalUit(){var t=0;S.klante.forEach(function(k){t+=saldo(k);});return t;}
function gesorteer(k){return k.inskrywings.slice().sort(function(a,b){
  return a.datum===b.datum? 0 : (a.datum<b.datum?-1:1);});}
function daeGelede(iso){if(!iso)return null;
  var a=new Date(iso+'T00:00:00'),b=new Date(vandagISO()+'T00:00:00');
  return Math.round((b-a)/86400000);}
function klantVan(kid){return S.klante.filter(function(k){return k.id===kid;})[0];}

/* periode-staat: alles ná laasteStaat */
function huidigeMaand(){ return vandagISO().slice(0,7); }
/* maand-staat: saldo aan die begin van die maand + alles in daardie maand */
function staatData(k, maand){
  maand = maand || huidigeMaand();
  var voor=k.open||0, rye=[];
  gesorteer(k).forEach(function(e){
    var m=e.datum.slice(0,7);
    if(m<maand){ voor+=tekenVan(e); } else if(m===maand){ rye.push(e); }
  });
  var aankope=0,betalings=0;
  rye.forEach(function(e){ if(e.tipe==='betaling') betalings+=e.bedrag; else aankope+=e.bedrag; });
  return {maand:maand, voor:voor, rye:rye, aankope:aankope, betalings:betalings,
          eind:voor+aankope-betalings, tot:vandagISO()};
}
function maandNaam(m){ return MAANDVOL[+m.slice(5,7)-1]+' '+m.slice(0,4); }
/* alle maande waarvoor daar iets is, plus die huidige, nuutste eerste */
function maandeVan(k){
  var st={}; st[huidigeMaand()]=1;
  k.inskrywings.forEach(function(e){ st[e.datum.slice(0,7)]=1; });
  return Object.keys(st).sort().reverse();
}

/* ============ UI-hulp ============ */
function h(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
var $=function(s){return document.querySelector(s);};

function toon(boodskap, ontdoenKiekie){
  laasteOntdoen=ontdoenKiekie||null;
  $('#toast-t').textContent=boodskap;
  $('#toast-b').hidden=!ontdoenKiekie;
  $('#toast').hidden=false;
  clearTimeout(toastTyd);
  toastTyd=setTimeout(function(){$('#toast').hidden=true;},4200);
}
$('#toast-b').onclick=function(){
  if(laasteOntdoen){herstelKiekie(laasteOntdoen);laasteOntdoen=null;}
  $('#toast').hidden=true;
};
function bladOop(html){ $('#blad').innerHTML='<div class="greep"></div>'+html; $('#oorlaag').hidden=false; }
function bladToe(){ $('#oorlaag').hidden=true; $('#blad').innerHTML=''; }
$('#oorlaag').onclick=function(e){ if(e.target===$('#oorlaag')) bladToe(); };
document.addEventListener('keydown',function(e){ if(e.key==='Escape') bladToe(); });

