/* ============ PDF ============ */
var MERK=[142,59,36], ROOM=[247,241,231], GRYS=[119,103,91], LYN=[228,219,205],
    INK=[42,27,20], BETGROEN=[47,107,69], LIG=[168,152,138];

var MONTHS_EN=['January','February','March','April','May','June','July','August','September','October','November','December'];
var MON_EN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
var TAAL={
  af:{staat:'Staat', stSp:'S T A A T', opgestel:'Opgestel', rekVan:'Rekening van', rekSp:'R E K E N I N G   V A N',
      beskr:'Beskrywing', datum:'Datum', bedrag:'Bedrag', saldo:'Saldo oorgedra', aankope:'Nuwe aankope',
      bet:'Betalings ontvang', betKort:'Betalings', uit:'Uitstaande', krediet:'In krediet',
      leeg:'Nog niks hierdie maand aangeteken nie.', dankie:'Baie dankie vir jou ondersteuning!', leer:'Staat'},
  en:{staat:'Statement', stSp:'S T A T E M E N T', opgestel:'Issued', rekVan:'Account of', rekSp:'A C C O U N T   O F',
      beskr:'Description', datum:'Date', bedrag:'Amount', saldo:'Balance brought forward', aankope:'New purchases',
      bet:'Payments received', betKort:'Payments', uit:'Amount due', krediet:'In credit',
      leeg:'Nothing recorded this month yet.', dankie:'Thank you for your support!', leer:'Statement'}
};
var ITEM_EN={'ete':'Meal','betaling':'Payment','droëwors':'Droëwors','biltong':'Biltong','haarsny':'Haircut','koeksisters':'Koeksisters'};
function taalVan(k){ return (k && k.taal==='en') ? 'en' : 'af'; }
function T(k){ return TAAL[taalVan(k)]; }
function itemNaam(beskr, tl){ if(tl!=='en') return beskr; var e=ITEM_EN[String(beskr).toLowerCase()]; return e||beskr; }
var NAAM_EN_STD="Crisna's Hot Kitchen", SLAG_EN_STD='Homemade meals & biltong';
function naamVan(tl){ var b=S.besigheid; if(tl==='en') return b.naamEn||NAAM_EN_STD; return b.naam; }
function slagVan(tl){ var b=S.besigheid; if(tl==='en') return b.slagEn||SLAG_EN_STD; return b.slag||''; }
function dKortT(iso,tl){ if(tl!=='en') return dKort(iso); var p=iso.split('-'); return (+p[2])+' '+MON_EN[+p[1]-1]; }
function dVolT(iso,tl){ if(tl!=='en') return dVol(iso); var p=iso.split('-'); return (+p[2])+' '+MON_EN[+p[1]-1]+' '+p[0]; }
function maandNaamT(m,tl){ if(tl!=='en') return maandNaam(m); return MONTHS_EN[+m.slice(5,7)-1]+' '+m.slice(0,4); }
function periodeTeks(dt,tl){ return maandNaamT(dt.maand,tl); }
function maakPdf(k, maand){
  var dt=staatData(k, maand), b=S.besigheid, tl=taalVan(k), W=T(k);
  var doc=new window.jspdf.jsPDF({unit:'mm',format:'a4'});
  var L=17, R=193, y;

  function kop(eerste){
    var nm=naamVan(tl);
    doc.setFont('helvetica','normal'); doc.setFontSize(9);
    doc.setTextColor(GRYS[0],GRYS[1],GRYS[2]);
    if(isStdNaam(nm)){
      pdfLogo(doc, L, 12, 15.5);
      doc.text(slagVan(tl), L, 32.8);
    } else {
      pdfIkoon(doc, L, 14.5, 12);
      doc.text(slagVan(tl), L+15.5, 27);
      doc.setTextColor(INK[0],INK[1],INK[2]);
      doc.setFont('times','bold'); doc.setFontSize(20);
      doc.text(nm, L+15.5, 21.5);
      doc.setFont('helvetica','normal');
    }
    doc.setFontSize(8); doc.setTextColor(LIG[0],LIG[1],LIG[2]);
    doc.text(W.stSp, R, 19.5, {align:'right'});
    doc.setFont('times','normal'); doc.setFontSize(13);
    doc.setTextColor(MERK[0],MERK[1],MERK[2]);
    doc.text(periodeTeks(dt,tl), R, 26.5, {align:'right'});
    doc.setFont('helvetica','normal'); doc.setFontSize(8);
    doc.setTextColor(GRYS[0],GRYS[1],GRYS[2]);
    doc.text(W.opgestel+' ' + dVolT(dt.tot,tl), R, 31.5, {align:'right'});
    doc.setDrawColor(MERK[0],MERK[1],MERK[2]); doc.setLineWidth(0.7);
    doc.line(L, 36, R, 36);
    if(eerste){
      doc.setFontSize(7.5); doc.setTextColor(LIG[0],LIG[1],LIG[2]);
      doc.text(W.rekSp, L, 45);
      doc.setFont('times','normal'); doc.setFontSize(17);
      doc.setTextColor(INK[0],INK[1],INK[2]);
      doc.text(k.naam, L, 52.5);
      return 62;
    }
    return 46;
  }
  function tabelkop(ty){
    doc.setFont('helvetica','bold'); doc.setFontSize(7.5);
    doc.setTextColor(GRYS[0],GRYS[1],GRYS[2]);
    doc.text(W.beskr.toUpperCase(), L, ty);
    doc.text(W.datum.toUpperCase(), 118, ty);
    doc.text(W.bedrag.toUpperCase(), R, ty, {align:'right'});
    doc.setDrawColor(LYN[0],LYN[1],LYN[2]); doc.setLineWidth(0.5);
    doc.line(L, ty+2, R, ty+2);
    return ty+2;
  }

  y=kop(true); y=tabelkop(y);

  /* saldo-reël */
  doc.setFillColor(ROOM[0],ROOM[1],ROOM[2]);
  doc.rect(L, y+0.6, R-L, 7, 'F');
  doc.setFont('helvetica','bold'); doc.setFontSize(10);
  doc.setTextColor(INK[0],INK[1],INK[2]);
  doc.text(W.saldo, L+2, y+5.5);
  doc.text(G(dt.voor), R-2, y+5.5, {align:'right'});
  y+=9.5;

  /* lang beskrywings breek na 'n volgende reël, sodat hulle nie oor die datum loop nie */
  var BESKR_W=96, REEL=4.2;
  function reels(e){
    doc.setFont('helvetica', e.tipe==='betaling'?'bold':'normal'); doc.setFontSize(10);
    return doc.splitTextToSize(String(itemNaam(e.beskr,tl)), BESKR_W);
  }
  var n=dt.rye.length, ekstra=0;
  dt.rye.forEach(function(e){ ekstra+=reels(e).length-1; });
  var beskikbaar=248-y-ekstra*REEL;
  var rh = n? Math.min(5.7, Math.max(4.1, beskikbaar/n)) : 5.7;

  dt.rye.forEach(function(e){
    var lyne=reels(e), hh=rh+(lyne.length-1)*REEL;
    if(y+hh>256){ doc.addPage(); y=tabelkop(kop(false)); y+=3; }
    var bet=e.tipe==='betaling';
    doc.setFont('helvetica', bet?'bold':'normal'); doc.setFontSize(10);
    if(bet) doc.setTextColor(BETGROEN[0],BETGROEN[1],BETGROEN[2]);
    else doc.setTextColor(INK[0],INK[1],INK[2]);
    lyne.forEach(function(t,i){ doc.text(t, L, y+rh-1.6+i*REEL); });
    if(!bet){ doc.setTextColor(GRYS[0],GRYS[1],GRYS[2]); doc.setFont('helvetica','normal'); }
    doc.text(dKortT(e.datum,tl), 118, y+rh-1.6);
    if(bet) doc.setTextColor(BETGROEN[0],BETGROEN[1],BETGROEN[2]);
    else doc.setTextColor(INK[0],INK[1],INK[2]);
    doc.setFont('helvetica', bet?'bold':'normal');
    doc.text((bet?'- ':'')+G(e.bedrag), R, y+rh-1.6, {align:'right'});
    doc.setDrawColor(239,235,226); doc.setLineWidth(0.3);
    doc.line(L, y+hh, R, y+hh);
    y+=hh;
  });
  if(!n){
    doc.setFont('helvetica','italic'); doc.setFontSize(9.5);
    doc.setTextColor(GRYS[0],GRYS[1],GRYS[2]);
    doc.text(W.leeg, L, y+6);
    y+=10;
  }

  /* opsomming */
  if(y>228){ doc.addPage(); y=kop(false)+4; }
  var sy=Math.min(y+12, 232), sx=123;
  function somry(t, w, groen){
    doc.setFont('helvetica','normal'); doc.setFontSize(10);
    doc.setTextColor(groen?BETGROEN[0]:INK[0], groen?BETGROEN[1]:INK[1], groen?BETGROEN[2]:INK[2]);
    doc.text(t, sx, sy); doc.text(w, R, sy, {align:'right'}); sy+=5.4;
  }
  somry(W.saldo, G(dt.voor));
  somry(W.aankope, G(dt.aankope));
  somry(W.bet, '- '+G(dt.betalings), true);
  doc.setDrawColor(LYN[0],LYN[1],LYN[2]); doc.setLineWidth(0.5);
  doc.line(sx, sy-3.4, R, sy-3.4);
  var krediet = dt.eind<0;
  if(krediet) doc.setFillColor(122,106,82); else doc.setFillColor(MERK[0],MERK[1],MERK[2]);
  doc.roundedRect(sx, sy-1, R-sx, 12.5, 1.2, 1.2, 'F');
  doc.setTextColor(255,255,255);
  doc.setFont('helvetica','bold'); doc.setFontSize(8.5);
  doc.text((krediet?W.krediet:W.uit).toUpperCase(), sx+3.5, sy+6.6);
  doc.setFont('times','bold'); doc.setFontSize(16);
  doc.text(G(Math.abs(dt.eind)), R-3.5, sy+7, {align:'right'});

  /* voet */
  doc.setDrawColor(231,225,213); doc.setLineWidth(0.4);
  doc.line(L, 273, R, 273);
  doc.setFont('times','italic'); doc.setFontSize(11);
  doc.setTextColor(MERK[0],MERK[1],MERK[2]);
  doc.text(W.dankie, L, 280);
  doc.setFont('helvetica','normal'); doc.setFontSize(8.5);
  doc.setTextColor(LIG[0],LIG[1],LIG[2]);
  doc.text(naamVan(tl), R, 277, {align:'right'});
  if(b.eienaar) doc.text(b.eienaar, R, 281.5, {align:'right'});
  return doc;
}
function pdfNaam(k, maand){
  maand=maand||huidigeMaand();
  var d=vandagISO().split('-'), tl=taalVan(k);
  var mn=(tl==='en'?MONTHS_EN:MAANDVOL)[+maand.slice(5,7)-1], dm=(tl==='en'?MON_EN:MAANDE)[+d[1]-1];
  return T(k).leer+'_'+k.naam.replace(/[^A-Za-z0-9]/g,'')+'_'+mn+maand.slice(0,4)+'_'+d[2]+dm+'.pdf';
}

/* ---- stuur / stoor sonder Claude ---- */
function kanDeelLeer(blob,naam){
  try{
    var f=new File([blob],naam,{type:blob.type});
    return !!(navigator.canShare && navigator.canShare({files:[f]}) && navigator.share);
  }catch(e){ return false; }
}
function afLaai(blob,naam){
  var u=URL.createObjectURL(blob), a=document.createElement('a');
  a.href=u; a.download=naam; a.rel='noopener';
  document.body.appendChild(a); a.click();
  setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(u);},4000);
}
/* gee terug: 'gedeel' | 'afgelaai' | 'afgekeur' | 'fout' */
function stuurLeer(blob,naam,titel){
  if(kanDeelLeer(blob,naam)){
    var f=new File([blob],naam,{type:blob.type});
    return navigator.share({files:[f],title:titel})
      .then(function(){return 'gedeel';})
      .catch(function(err){
        if(err && (err.name==='AbortError'||err.name==='NotAllowedError')) return 'afgekeur';
        try{ afLaai(blob,naam); return 'afgelaai'; }catch(e){ return 'fout'; }
      });
  }
  try{ afLaai(blob,naam); return Promise.resolve('afgelaai'); }
  catch(e){ return Promise.resolve('fout'); }
}
function stuurStaat(k, maand){
  var blob;
  try{ blob=maakPdf(k, maand).output('blob'); }catch(e){ return Promise.resolve('fout'); }
  return stuurLeer(blob, pdfNaam(k, maand), T(k).leer+' - '+k.naam);
}

/* ============ staat-voorskou ============ */
function staatHtml(k, maand){
  var dt=staatData(k, maand), b=S.besigheid, tl=taalVan(k), W=T(k);
  var rye='<tr class="sal"><td>'+W.saldo+'</td><td></td><td class="rg">'+G(dt.voor)+'</td></tr>';
  dt.rye.forEach(function(e){
    var bet=e.tipe==='betaling';
    rye+='<tr'+(bet?' class="btl"':'')+'><td>'+h(itemNaam(e.beskr,tl))+'</td><td>'+h(dKortT(e.datum,tl))
      +'</td><td class="rg">'+(bet?'&minus; ':'')+G(e.bedrag)+'</td></tr>';
  });
  if(!dt.rye.length) rye+='<tr><td colspan="3" style="color:#8A8378;font-style:italic;padding:8px 0">'+W.leeg+'</td></tr>';
  var krediet=dt.eind<0;
  return '<div class="staat" id="staat-voorskou">'
    + '<div class="sk"><div>'+(isStdNaam(naamVan(tl))
        ? logoSvg('#2A1B14','#8E3B24','staatlogo')+'<div class="sl">'+h(slagVan(tl))+'</div>'
        : '<div class="merkry">'+ikoonSvg('#8E3B24','#F5EDE0','ik')+'<div><h4>'+h(naamVan(tl))+'</h4>'
          + '<div class="sl">'+h(slagVan(tl))+'</div></div></div>')+'</div>'
    + '<div class="r"><div class="e">'+W.staat+'</div><div class="m">'+h(periodeTeks(dt,tl))+'</div></div></div>'
    + '<div class="aan"><div class="e">'+W.rekVan+'</div><div class="n">'+h(k.naam)+'</div></div>'
    + '<table><thead><tr><th>'+W.beskr+'</th><th>'+W.datum+'</th><th class="rg">'+W.bedrag+'</th></tr></thead>'
    + '<tbody>'+rye+'</tbody></table>'
    + '<div class="som">'
    + '<div class="sr"><span>'+W.saldo+'</span><span>'+G(dt.voor)+'</span></div>'
    + '<div class="sr"><span>'+W.aankope+'</span><span>'+G(dt.aankope)+'</span></div>'
    + '<div class="sr g"><span>'+W.betKort+'</span><span>&minus; '+G(dt.betalings)+'</span></div>'
    + '<div class="tot"'+(krediet?' style="background:#7A6A52"':'')+'><span class="t1">'
    + (krediet?W.krediet:W.uit)+'</span><span class="t2">'+G(Math.abs(dt.eind))+'</span></div>'
    + '</div>'
    + '<div class="vt"><span class="dk">'+W.dankie+'</span>'
    + '<span class="kl">'+h(naamVan(tl))+'<br>'+h(b.eienaar)+'</span></div></div>';
}

function bladStaat(k, maand){
  maand = maand || huidigeMaand();
  var opsies=maandeVan(k).map(function(m){
    return '<option value="'+m+'"'+(m===maand?' selected':'')+'>'+h(maandNaam(m))+'</option>';
  }).join('');
  bladOop('<h3>Staat vir '+h(k.naam)+'</h3>'
    + '<div class="veld"><label for="st-maand">Maand</label><select id="st-maand">'+opsies+'</select></div>'
    + '<div class="veld"><label>Taal van die staat</label><div class="knoppe">'
    + '<button class="knop'+(taalVan(k)==='af'?'':' sag')+'" data-taal="af" style="min-height:42px">Afrikaans</button>'
    + '<button class="knop'+(taalVan(k)==='en'?'':' sag')+'" data-taal="en" style="min-height:42px">English</button></div></div>'
    + '<p class="hint">Die staat wys die hele maand se items, elke keer &mdash; hoeveel keer jy dit ook al stuur. Tik <strong>Stuur staat</strong>, dan kies jy WhatsApp uit die deel-skerm.</p>'
    + staatHtml(k, maand)
    + '<div class="knoppe" style="margin-top:16px"><button class="knop sag" data-toe>Toemaak</button>'
    + '<button class="knop" data-stoorpdf="'+k.id+'" data-maand="'+maand+'">Stuur staat</button></div>'
    + '<p style="text-align:center;margin:14px 0 0"><button class="skakel" data-gemerk="'+k.id+'">Merk as gestuur sonder PDF</button></p>');
  var sel=$('#st-maand'); if(sel) sel.onchange=function(){ bladStaat(k, sel.value); };
  [].forEach.call(document.querySelectorAll('#blad [data-taal]'),function(b){
    b.onclick=function(ev){ ev.stopPropagation(); k.taal=b.getAttribute('data-taal'); stoor(); bladStaat(k, sel?sel.value:maand); };
  });
}

/* ============ state vir almal ============ */
function bladAlmal(){
  var lys=S.klante.map(function(k){
    var d=daeGelede(k.laasteStaat);
    var sub = d===null?'Nog nooit gestuur':(d===0?'Vandag gestuur':(d===1?'Gister gestuur':d+' dae gelede gestuur'));
    return '<div class="instel-item" id="al-'+k.id+'"><div class="d"><div class="naam">'+h(k.naam)+'</div>'
      + '<div class="p"><span class="num">'+G(saldo(k))+'</span> &middot; '+h(sub)+(taalVan(k)==='en'?' &middot; English':'')+'</div></div>'
      + '<button class="knop sag" style="width:auto;min-height:40px;padding:0 14px" data-stuur-een="'+k.id+'">Stuur</button></div>';
  }).join('');
  bladOop('<h3>State stuur</h3>'
    + '<p class="hint">Tik <strong>Stuur</strong> langs elke naam. Jou foon wys die deel-skerm &mdash; kies WhatsApp en die PDF gaan reguit na hom toe.</p>'
    + lys
    + '<div class="knoppe" style="margin-top:16px"><button class="knop" data-toe>Klaar</button></div>');
}

/* ============ blaaie vir invoer ============ */
function veldGetal(idn,lab,waarde){
  return '<div class="veld"><label for="'+idn+'">'+lab+'</label>'
    + '<input id="'+idn+'" type="text" inputmode="decimal" value="'+h(waarde)+'"></div>';
}
function veldDatum(idn,lab,waarde){
  return '<div class="veld"><label for="'+idn+'">'+lab+'</label>'
    + '<input id="'+idn+'" type="date" value="'+h(waarde)+'"></div>';
}
function getal(idn){var t=String(($('#'+idn)||{}).value||'');
  t=t.indexOf('.')<0 ? t.replace(/,/g,'.') : t.replace(/,/g,''); // "12,50" is 12.50
  var v=parseFloat(t.replace(/[^0-9.\-]/g,''));
  return isFinite(v)?v:0;}

function bladAnder(k){
  bladOop('<h3>Ander item</h3>'
    + '<div class="veld"><label for="a-beskr">Wat is dit?</label><input id="a-beskr" value="" placeholder="bv. Koeksisters"></div>'
    + '<div class="veld-twee">'
    +   '<div class="veld"><label for="a-aantal">Hoeveel</label><input id="a-aantal" type="text" inputmode="numeric" value="1"></div>'
    +   veldGetal('a-prys','Prys elk',k.anderPrys||'')
    + '</div>'
    + veldGetal('a-bedrag','Bedrag (totaal)',k.anderPrys||'')
    + veldDatum('a-datum','Datum',vandagISO())
    + '<div class="knoppe"><button class="knop sag" data-toe>Kanselleer</button>'
    + '<button class="knop" data-ander-stoor="'+k.id+'">Voeg by</button></div>');
  // Hoeveel × prys elk vul die totaal in; sy kan die totaal steeds self verander.
  var reken=function(){ var p=getal('a-prys'); if(p) $('#a-bedrag').value=String(Math.round(getal('a-aantal')*p*100)/100); };
  $('#a-aantal').oninput=reken; $('#a-prys').oninput=reken;
  setTimeout(function(){var el=$('#a-beskr'); if(el) el.focus();},60);
}
