/* ============ aksies ============ */
function voegBy(k,beskr,bedrag,datum,tipe){
  var voor=kiekie();
  k.inskrywings.push({id:id(),tipe:tipe||'item',beskr:beskr,bedrag:bedrag,datum:datum});
  stoor(); teken();
  toon(beskr+' bygevoeg', voor);
}

function bindAksies(){
  var app=$('#app');
  app.querySelectorAll('[data-gaan]').forEach(function(el){
    el.onclick=function(){gaan('klant',el.getAttribute('data-gaan'));};});
  var t=app.querySelector('[data-terug]'); if(t) t.onclick=function(){gaan('huis');};
  var ins=app.querySelector('[data-instel]'); if(ins) ins.onclick=function(){gaan('instellings');};
  var nk=app.querySelector('[data-nuweklant]'); if(nk) nk.onclick=bladNuweKlant;
  app.querySelectorAll('[data-oortjie]').forEach(function(el){
    el.onclick=function(){ var n=el.getAttribute('data-oortjie'); if(n!==V.naam){ V={naam:n,kid:null}; teken(); } };});
  if(V.naam==='geld') bindGeld(app);
  var sa=app.querySelector('[data-statealmal]'); if(sa) sa.onclick=function(){
    if(!S.klante.length){toon('Nog geen klante nie');return;} bladAlmal();};

  var k=V.naam==='klant'? klantVan(V.kid) : null;
  if(k){
    app.querySelectorAll('[data-item]').forEach(function(el){
      el.onclick=function(){
        var it=S.items.filter(function(x){return x.id===el.getAttribute('data-item');})[0];
        if(it) voegBy(k,it.naam,it.prys,vandagISO());
      };});
    var an=app.querySelector('[data-ander]'); if(an) an.onclick=function(){bladAnder(k);};
    var bt=app.querySelector('[data-betaling]'); if(bt) bt.onclick=function(){bladBetaling(k);};
    app.querySelectorAll('[data-ins]').forEach(function(el){
      el.onclick=function(){
        var e=k.inskrywings.filter(function(x){return x.id===el.getAttribute('data-ins');})[0];
        if(e) bladInskrywing(k,e);
      };});
    var ob=app.querySelector('[data-openbal]'); if(ob) ob.onclick=function(){
      bladOop('<h3>Ou saldo</h3><p class="hint">Wat het '+h(k.naam)+' geskuld voordat jy die app begin gebruik het?</p>'
        + veldGetal('o-bed','Bedrag',k.open||0)
        + '<div class="knoppe"><button class="knop sag" data-toe>Kanselleer</button>'
        + '<button class="knop" id="o-stoor">Stoor</button></div>');
      $('#o-stoor').onclick=function(){var voor=kiekie();k.open=getal('o-bed');stoor();bladToe();teken();toon('Ou saldo verander',voor);};
    };
    var st=app.querySelector('[data-staat]'); if(st) st.onclick=function(){bladStaat(k);};
    var hn=app.querySelector('[data-hernoem]'); if(hn) hn.onclick=function(){
      bladOop('<h3>Naam verander</h3><div class="veld"><label for="h-naam">Naam</label>'
        + '<input id="h-naam" value="'+h(k.naam)+'"></div>'
        + '<div class="knoppe"><button class="knop sag" data-toe>Kanselleer</button>'
        + '<button class="knop" id="h-stoor">Stoor</button></div>');
      $('#h-stoor').onclick=function(){var v=$('#h-naam').value.trim(); if(!v)return;
        var voor=kiekie(); k.naam=v; stoor(); bladToe(); teken(); toon('Naam verander',voor);};
    };
    var vk=app.querySelector('[data-verwyderklant]'); if(vk) vk.onclick=function(){
      bladBevestig('Verwyder '+k.naam+'?','Al sy inskrywings gaan saam weg. Jy kan dit dadelik ontdoen.',
        'Ja, verwyder', function(){
          var voor=kiekie();
          S.klante=S.klante.filter(function(x){return x.id!==k.id;});
          stoor(); gaan('huis'); toon(k.naam+' verwyder', voor);
        });
    };
  }

  if(V.naam==='instellings'){
    var sb=app.querySelector('[data-stoorbesigheid]'); if(sb) sb.onclick=function(){
      var voor=kiekie();
      S.besigheid.naam=$('#i-naam').value.trim()||S.besigheid.naam;
      S.besigheid.slag=$('#i-slag').value.trim();
      S.besigheid.naamEn=$('#i-naamen').value.trim()||NAAM_EN_STD;
      S.besigheid.slagEn=$('#i-slagen').value.trim()||SLAG_EN_STD;
      S.besigheid.eienaar=$('#i-eien').value.trim();
      S.besigheid.geld=$('#i-geld').value.trim()||'$';
      stoor(); teken(); toon('Gestoor', voor);
    };
    var ni=app.querySelector('[data-nuweitem]'); if(ni) ni.onclick=function(){bladItem(null);};
    app.querySelectorAll('[data-wysigitem]').forEach(function(el){
      el.onclick=function(){
        var it=S.items.filter(function(x){return x.id===el.getAttribute('data-wysigitem');})[0];
        if(it) bladItem(it);
      };});
    var rg=app.querySelector('[data-rugsteun]'); if(rg) rg.onclick=doenRugsteun;
    var hs=app.querySelector('[data-herstel]'); if(hs) hs.onclick=bladHerstel;
    var wa=app.querySelector('[data-wisalles]'); if(wa) wa.onclick=function(){
      bladBevestig('Vee alle data uit?','Elke klant, inskrywing, uitgawe en kontantverkoop word uitgevee. Jou items en besigheid-besonderhede bly. Maak eers &rsquo;n rugsteun.',
        'Ja, vee uit', function(){
          var voor=kiekie();
          S={v:1,besigheid:S.besigheid,items:S.items,klante:[],kategoriee:S.kategoriee};
          migreer(); stoor(); gaan('huis'); toon('Alles uitgevee', voor);
        });
    };
  }
}

/* blad-knoppies (gedelegeer) */
$('#blad').addEventListener('click', function(ev){
  var el=ev.target.closest('button'); if(!el) return;
  var a=function(n){return el.getAttribute(n);};
  if(el.hasAttribute('data-toe')) return bladToe();

  if(a('data-ander-stoor')){
    var k=klantVan(a('data-ander-stoor'));
    var b=$('#a-beskr').value.trim()||'Item', bed=getal('a-bedrag'), dat=$('#a-datum').value||vandagISO();
    var n=getal('a-aantal'), pe=getal('a-prys');
    if(!bed){toon('Vul ’n bedrag in');return;}
    if(n>1 && !new RegExp('x\\s*'+n+'\\b','i').test(b)) b+=' x '+n;
    if(pe) k.anderPrys=pe;
    bladToe(); voegBy(k,b,bed,dat); return;
  }
  if(a('data-bet-stoor')){
    var k2=klantVan(a('data-bet-stoor')), bed2=getal('b-bedrag'), dat2=$('#b-datum').value||vandagISO();
    if(!bed2){toon('Vul ’n bedrag in');return;}
    bladToe(); voegBy(k2,'Betaling',bed2,dat2,'betaling'); return;
  }
  if(a('data-ins-stoor')||a('data-ins-weg')){
    var kid=V.kid, kk=klantVan(kid), eid=a('data-ins-stoor')||a('data-ins-weg');
    var voor=kiekie();
    if(a('data-ins-weg')){
      kk.inskrywings=kk.inskrywings.filter(function(x){return x.id!==eid;});
      bladToe(); stoor(); teken(); toon('Verwyder', voor); return;
    }
    var e=kk.inskrywings.filter(function(x){return x.id===eid;})[0];
    if(!getal('w-bedrag')){toon('Vul ’n bedrag in');return;}
    e.beskr=$('#w-beskr').value.trim()||e.beskr; e.bedrag=getal('w-bedrag'); e.datum=$('#w-datum').value||e.datum;
    bladToe(); stoor(); teken(); toon('Gestoor', voor); return;
  }
  if(el.hasAttribute('data-klant-stoor')){
    var naam=$('#n-naam').value.trim(); if(!naam){toon('Vul ’n naam in');return;}
    var voor2=kiekie();
    var nuut={id:id(),naam:naam,open:getal('n-open'),inskrywings:[],laasteStaat:null};
    S.klante.push(nuut); stoor(); bladToe(); gaan('klant',nuut.id); toon(naam+' bygevoeg', voor2); return;
  }
  if(a('data-item-stoor')!==null && el.hasAttribute('data-item-stoor')){
    var itid=a('data-item-stoor'), nm=$('#it-naam').value.trim(), pr=getal('it-prys');
    if(!nm){toon('Vul ’n naam in');return;}
    var voor3=kiekie();
    if(itid){ var it=S.items.filter(function(x){return x.id===itid;})[0]; it.naam=nm; it.prys=pr; }
    else S.items.push({id:id(),naam:nm,prys:pr});
    stoor(); bladToe(); teken(); toon('Gestoor', voor3); return;
  }
  if(a('data-item-weg')){
    var voor4=kiekie();
    S.items=S.items.filter(function(x){return x.id!==a('data-item-weg');});
    stoor(); bladToe(); teken(); toon('Item verwyder', voor4); return;
  }
  if(a('data-stoorpdf')){
    var kp=klantVan(a('data-stoorpdf')), mp=a('data-maand')||huidigeMaand();
    el.disabled=true; el.textContent='Besig…';
    stuurStaat(kp, mp).then(function(r){
      el.disabled=false; el.textContent='Stuur staat';
      if(r==='gedeel'||r==='afgelaai'){
        var voor5=kiekie(); kp.laasteStaat=vandagISO(); stoor(); bladToe(); teken();
        toon(r==='gedeel'?'Gestuur en gemerk':'PDF afgelaai en gemerk', voor5);
      }
      else if(r==='afgekeur') toon('Nie gestuur nie');
      else toon('Kon nie die PDF maak nie');
    });
    return;
  }
  if(a('data-gemerk')){
    var kg=klantVan(a('data-gemerk')), voor6=kiekie();
    kg.laasteStaat=vandagISO(); stoor(); bladToe(); teken(); toon('Gemerk as gestuur', voor6); return;
  }
  if(a('data-stuur-een')){
    var ka=klantVan(a('data-stuur-een'));
    el.disabled=true; el.textContent='…';
    stuurStaat(ka).then(function(r){
      el.disabled=false;
      if(r==='gedeel'||r==='afgelaai'){
        var voorA=kiekie(); ka.laasteStaat=vandagISO(); stoor();
        el.textContent='Gestuur'; el.style.color='var(--bet)';
        var sub=document.querySelector('#al-'+ka.id+' .p'); if(sub) sub.textContent=G(saldo(ka))+' · vandag gestuur';
        teken(); toon(ka.naam+' se staat is gestuur', voorA);
      } else { el.textContent='Stuur'; toon(r==='afgekeur'?'Nie gestuur nie':'Kon nie die PDF maak nie'); }
    });
    return;
  }
  if(el.hasAttribute('data-herstel-doen')){
    var teks=$('#hs-teks').value.trim();
    try{
      var nuwe=JSON.parse(teks);
      if(!nuwe || !nuwe.klante) throw 0;
      var voor7=kiekie(); S=nuwe; migreer(); stoor(); bladToe(); gaan('huis'); toon('Data herstel', voor7);
    }catch(err){ toon('Die teks lyk nie soos ’n rugsteun nie'); }
    return;
  }
});

function doenRugsteun(){
  var data=JSON.stringify(S,null,1);
  var blob=new Blob([data],{type:'application/json'});
  var naam='Kombuis_rugsteun_'+vandagISO()+'.json';
  stuurLeer(blob,naam,'Rugsteun van my boek').then(function(r){
    if(r==='gedeel') toon('Rugsteun gestuur');
    else if(r==='afgelaai') toon('Rugsteun afgelaai');
    else bladHerstel(data);
  });
}
function bladHerstel(vooraf){
  bladOop('<h3>'+(vooraf?'Rugsteun':'Herstel data')+'</h3>'
    + '<p class="hint">'+(vooraf
        ? 'Kopieer hierdie teks en stuur dit vir jouself op WhatsApp of e-pos. Dit is jou hele boek.'
        : 'Plak &rsquo;n vorige rugsteun hier in. Dit vervang alles wat nou in die app is.')+'</p>'
    + '<div class="veld"><label for="hs-teks">'+(vooraf?'Jou data':'Rugsteun-teks')+'</label>'
    + '<textarea id="hs-teks" spellcheck="false">'+h(vooraf||'')+'</textarea></div>'
    + '<div class="knoppe"><button class="knop sag" data-toe>Toemaak</button>'
    + (vooraf?'<button class="knop" id="hs-kop">Kopieer</button>'
             :'<button class="knop" data-herstel-doen>Herstel</button>')+'</div>');
  if(vooraf){
    $('#hs-kop').onclick=function(){
      var ta=$('#hs-teks'); ta.select(); ta.setSelectionRange(0,999999);
      try{
        if(navigator.clipboard) navigator.clipboard.writeText(ta.value).then(function(){toon('Gekopieer');},function(){document.execCommand('copy');toon('Gekopieer');});
        else { document.execCommand('copy'); toon('Gekopieer'); }
      }catch(e){ toon('Hou die teks in en kies Kopieer'); }
    };
  }
}


/* ============ inkomste & uitgawes ============ */
var KAT_STD=['Vleis & kos','Kruideniers','Verpakking','Gas & krag','Vervoer','Ander'];
function migreer(){
  if(!S.uitgawes) S.uitgawes=[];
  if(!S.inkomste) S.inkomste=[];
  if(!S.kategoriee || !S.kategoriee.length) S.kategoriee=KAT_STD.slice();
}
var GM=null;
function oortjies(akt){
  return '<div class="oortjies" role="tablist">'
    + '<button class="oortjie'+(akt==='huis'?' aan':'')+'" data-oortjie="huis" role="tab">Klante</button>'
    + '<button class="oortjie'+(akt==='geld'?' aan':'')+'" data-oortjie="geld" role="tab">Geld</button></div>';
}
function inMaand(iso,m){ return iso && iso.slice(0,7)===m; }
function geldData(m){
  var verkope=0, ontvang=0, kontant=0, uit=0, perItem={}, perKat={};
  S.klante.forEach(function(k){ k.inskrywings.forEach(function(e){
    if(!inMaand(e.datum,m)) return;
    if(e.tipe==='betaling') ontvang+=e.bedrag;
    else { verkope+=e.bedrag; perItem[e.beskr]=(perItem[e.beskr]||0)+e.bedrag; }
  });});
  S.inkomste.forEach(function(e){ if(!inMaand(e.datum,m)) return;
    kontant+=e.bedrag; verkope+=e.bedrag; perItem[e.beskr]=(perItem[e.beskr]||0)+e.bedrag; });
  S.uitgawes.forEach(function(e){ if(!inMaand(e.datum,m)) return;
    uit+=e.bedrag; perKat[e.kategorie]=(perKat[e.kategorie]||0)+e.bedrag; });
  var ingekom=ontvang+kontant;
  return {verkope:verkope, ontvang:ontvang, kontant:kontant, ingekom:ingekom, uit:uit,
          wins:ingekom-uit, perItem:perItem, perKat:perKat};
}
function alleMaande(){
  var st={}; st[huidigeMaand()]=1;
  S.klante.forEach(function(k){ k.inskrywings.forEach(function(e){ st[e.datum.slice(0,7)]=1; }); });
  S.inkomste.concat(S.uitgawes).forEach(function(e){ st[e.datum.slice(0,7)]=1; });
  return Object.keys(st).sort().reverse();
}
function stawe(obj, klas){
  var ks=Object.keys(obj).sort(function(a,b){return obj[b]-obj[a];});
  if(!ks.length) return '<p class="leeg" style="padding:12px">Niks hierdie maand nie.</p>';
  var mx=obj[ks[0]]||1;
  return ks.map(function(k){
    return '<div class="staaf '+(klas||'')+'"><span class="n">'+h(k)+'</span>'
      + '<span class="spoor"><span class="vul" style="width:'+Math.max(3,Math.round(obj[k]/mx*100))+'%"></span></span>'
      + '<span class="w num">'+G(obj[k])+'</span></div>';
  }).join('');
}
function skermGeld(){
  var b=S.besigheid, m=GM||huidigeMaand(), d=geldData(m);
  var opsies=alleMaande().map(function(x){
    return '<option value="'+x+'"'+(x===m?' selected':'')+'>'+h(maandNaam(x))+'</option>';}).join('');
  var lys=S.uitgawes.filter(function(e){return inMaand(e.datum,m);}).map(function(e){return {t:'u',e:e};})
    .concat(S.inkomste.filter(function(e){return inMaand(e.datum,m);}).map(function(e){return {t:'i',e:e};}))
    .sort(function(a,b){return a.e.datum<b.e.datum?1:(a.e.datum>b.e.datum?-1:0);});
  var rye=lys.map(function(x){
    var e=x.e, u=x.t==='u';
    return '<button class="ry '+(u?'uitg':'ink')+'" data-geldry="'+x.t+':'+e.id+'">'
      + '<span class="d"><span class="naam">'+h(e.beskr||e.kategorie)+'</span>'
      + '<span class="dat">'+h(dVol(e.datum))+(u?' &middot; '+h(e.kategorie):' &middot; Kontantverkoop')+'</span></span>'
      + '<span class="bed num">'+(u?'&minus; ':'+ ')+G(e.bedrag)+'</span></button>';
  }).join('') || '<p class="leeg">Nog geen uitgawes of kontantverkope hierdie maand nie.<br>Tik die knoppies onder om een by te voeg.</p>';
  var ms=alleMaande().slice(0,6), tr=ms.map(function(x){
    var g=geldData(x);
    return '<tr'+(x===m?' class="huidig"':'')+'><td>'+h(MAANDE[+x.slice(5,7)-1]+' '+x.slice(2,4))+'</td>'
      + '<td class="num">'+G(g.ingekom)+'</td><td class="num">'+G(g.uit)+'</td>'
      + '<td class="num '+(g.wins<0?'neg':'pos')+'">'+G(g.wins)+'</td></tr>';
  }).join('');
  var nUit=S.uitgawes.filter(function(e){return inMaand(e.datum,m);}).length;
  return '<header class="kop"><div>'+kopNaam(b)+'<div class="slag">'+h(b.slag)+'</div></div>'
    + '<button class="ikoon" data-instel aria-label="Instellings">'+RAT+'</button></header>'
    + oortjies('geld')
    + '<div class="veld"><label for="g-maand">Maand</label><select id="g-maand">'+opsies+'</select></div>'
    + '<div class="wins'+(d.wins<0?' verlies':'')+'"><div><div class="l">'+(d.wins<0?'Verlies':'Wins')+' hierdie maand</div>'
    + '<div class="sub">Geld ingekom min uitgawes</div></div>'
    + '<span class="b num">'+G(d.wins)+'</span></div>'
    + '<div class="syfers">'
    + '<div class="syfer in"><div class="l">Ingekom</div><div class="b num">'+G(d.ingekom)+'</div>'
    + '<div class="s">Betalings '+G(d.ontvang)+(d.kontant?' + kontant '+G(d.kontant):'')+'</div></div>'
    + '<div class="syfer uit"><div class="l">Uitgawes</div><div class="b num">'+G(d.uit)+'</div>'
    + '<div class="s">'+nUit+(nUit===1?' aankoop':' aankope')+'</div></div>'
    + '<div class="syfer"><div class="l">Verkoop</div><div class="b num">'+G(d.verkope)+'</div>'
    + '<div class="s">Betaal of nie</div></div>'
    + '<div class="syfer"><div class="l">Klante skuld</div><div class="b num">'+G(totaalUit())+'</div>'
    + '<div class="s">Altesaam, vandag</div></div>'
    + '</div>'
    + '<div class="afdeling"><span class="eyebrow">Wat jy verkoop het</span></div>'
    + stawe(d.perItem)
    + '<div class="afdeling"><span class="eyebrow">Waarop jy geld uitgegee het</span></div>'
    + stawe(d.perKat,'uit')
    + '<div class="afdeling"><span class="eyebrow">Uitgawes &amp; kontantverkope</span></div>'
    + rye
    + '<div class="afdeling"><span class="eyebrow">Laaste maande</span></div>'
    + '<table class="tabel"><thead><tr><th>Maand</th><th>In</th><th>Uit</th><th>Wins</th></tr></thead><tbody>'+tr+'</tbody></table>'
    + '<p class="voetnota">&ldquo;Ingekom&rdquo; is geld wat jy werklik gekry het.<br>&ldquo;Verkoop&rdquo; sluit in wat klante nog skuld.</p>'
    + '<div class="balk"><div class="binne">'
    + '<button class="knop sag" data-nuweink>+ Kontant</button>'
    + '<button class="knop" data-nuweuitg>+ Uitgawe</button>'
    + '</div></div>';
}
function bindGeld(app){
  var sel=app.querySelector('#g-maand'); if(sel) sel.onchange=function(){ GM=sel.value; teken(); };
  var nu=app.querySelector('[data-nuweuitg]'); if(nu) nu.onclick=function(){ bladUitgawe(null); };
  var ni=app.querySelector('[data-nuweink]'); if(ni) ni.onclick=function(){ bladInkomste(null); };
  app.querySelectorAll('[data-geldry]').forEach(function(el){
    el.onclick=function(){
      var p=el.getAttribute('data-geldry').split(':');
      if(p[0]==='u'){ var e=S.uitgawes.filter(function(x){return x.id===p[1];})[0]; if(e) bladUitgawe(e); }
      else { var e2=S.inkomste.filter(function(x){return x.id===p[1];})[0]; if(e2) bladInkomste(e2); }
    };});
}
function standaardDatum(){ var m=GM||huidigeMaand(); return m===huidigeMaand()? vandagISO() : m+'-01'; }
function bladUitgawe(e, voorKat, voorWaardes){
  var nuut=!e, kat=voorKat||(nuut? S.kategoriee[0] : e.kategorie);
  var chips=S.kategoriee.map(function(k){
    return '<button class="chip'+(k===kat?' aan':'')+'" data-kat="'+h(k)+'">'+h(k)+'</button>';}).join('')
    + '<button class="chip" data-nuwekat>+ Nuwe</button>';
  var w=voorWaardes||{};
  bladOop('<h3>'+(nuut?'Nuwe uitgawe':'Uitgawe')+'</h3>'
    + '<div class="veld"><label>Waarvoor?</label></div><div class="kat-chips">'+chips+'</div>'
    + '<div id="u-nuwekat" hidden><div class="veld"><label for="u-katnaam">Nuwe kategorie</label><input id="u-katnaam" placeholder="bv. Gereedskap"></div>'
    + '<button class="knop sag" id="u-katvoeg" style="margin-bottom:13px">Voeg kategorie by</button></div>'
    + veldGetal('u-bedrag','Bedrag', w.bedrag!=null?w.bedrag:(nuut?'':e.bedrag))
    + '<div class="veld"><label for="u-beskr">Nota (opsioneel)</label><input id="u-beskr" value="'+h(w.beskr!=null?w.beskr:(nuut?'':(e.beskr||'')))+'" placeholder="bv. Beesvleis by Spar"></div>'
    + veldDatum('u-datum','Datum', w.datum||(nuut?standaardDatum():e.datum))
    + '<div class="knoppe">'
    + (nuut?'<button class="knop sag" data-toe>Kanselleer</button>':'<button class="knop gevaar" id="u-weg">Verwyder</button>')
    + '<button class="knop" id="u-stoor">Stoor</button></div>');
  [].forEach.call(document.querySelectorAll('#blad [data-kat]'),function(c){
    c.onclick=function(ev){ ev.stopPropagation(); kat=c.getAttribute('data-kat');
      [].forEach.call(document.querySelectorAll('#blad [data-kat]'),function(x){ x.classList.toggle('aan', x===c); }); }; });
  $('#blad [data-nuwekat]').onclick=function(ev){ ev.stopPropagation(); $('#u-nuwekat').hidden=false; $('#u-katnaam').focus(); };
  $('#u-katvoeg').onclick=function(ev){
    ev.stopPropagation();
    var n=$('#u-katnaam').value.trim(); if(!n) return;
    if(S.kategoriee.indexOf(n)<0){ S.kategoriee.splice(Math.max(0,S.kategoriee.length-1),0,n); stoor(); }
    bladUitgawe(e, n, {bedrag:$('#u-bedrag').value, beskr:$('#u-beskr').value, datum:$('#u-datum').value});
  };
  $('#u-stoor').onclick=function(){
    var bed=getal('u-bedrag'); if(!bed){ toon('Vul die bedrag in'); return; }
    var voor=kiekie(), dat=$('#u-datum').value||vandagISO(), bs=$('#u-beskr').value.trim();
    if(nuut) S.uitgawes.push({id:id(),datum:dat,kategorie:kat,beskr:bs,bedrag:bed});
    else { e.datum=dat; e.kategorie=kat; e.beskr=bs; e.bedrag=bed; }
    GM=dat.slice(0,7); stoor(); bladToe(); teken(); toon(nuut?'Uitgawe gestoor':'Gestoor', voor);
  };
  var wg=$('#u-weg'); if(wg) wg.onclick=function(){
    var voor=kiekie(); S.uitgawes=S.uitgawes.filter(function(x){return x.id!==e.id;});
    stoor(); bladToe(); teken(); toon('Uitgawe verwyder', voor);
  };
}
function bladInkomste(e){
  var nuut=!e;
  var chips=S.items.map(function(it){
    return '<button class="chip" data-inkitem="'+it.id+'">'+h(it.naam)+'<span class="p num">'+G(it.prys)+'</span></button>';}).join('');
  bladOop('<h3>Kontantverkoop</h3>'
    + '<p class="hint">Vir iemand wat dadelik betaal en nie &rsquo;n rekening by jou het nie.</p>'
    + (nuut?'<div class="kat-chips">'+chips+'</div>':'')
    + '<div class="veld"><label for="k-beskr">Wat is verkoop?</label><input id="k-beskr" value="'+h(nuut?'':e.beskr)+'" placeholder="bv. Biltong"></div>'
    + veldGetal('k-bedrag','Bedrag', nuut?'':e.bedrag)
    + veldDatum('k-datum','Datum', nuut?standaardDatum():e.datum)
    + '<div class="knoppe">'
    + (nuut?'<button class="knop sag" data-toe>Kanselleer</button>':'<button class="knop gevaar" id="k-weg">Verwyder</button>')
    + '<button class="knop" id="k-stoor">Stoor</button></div>');
  [].forEach.call(document.querySelectorAll('#blad [data-inkitem]'),function(c){
    c.onclick=function(ev){ ev.stopPropagation();
      var it=S.items.filter(function(x){return x.id===c.getAttribute('data-inkitem');})[0];
      if(it){ $('#k-beskr').value=it.naam; $('#k-bedrag').value=it.prys; } };});
  $('#k-stoor').onclick=function(){
    var bed=getal('k-bedrag'); if(!bed){ toon('Vul die bedrag in'); return; }
    var voor=kiekie(), dat=$('#k-datum').value||vandagISO(), bs=$('#k-beskr').value.trim()||'Kontantverkoop';
    if(nuut) S.inkomste.push({id:id(),datum:dat,beskr:bs,bedrag:bed});
    else { e.datum=dat; e.beskr=bs; e.bedrag=bed; }
    GM=dat.slice(0,7); stoor(); bladToe(); teken(); toon(nuut?'Verkoop gestoor':'Gestoor', voor);
  };
  var wg=$('#k-weg'); if(wg) wg.onclick=function(){
    var voor=kiekie(); S.inkomste=S.inkomste.filter(function(x){return x.id!==e.id;});
    stoor(); bladToe(); teken(); toon('Verwyder', voor);
  };
}

/* ============ begin ============ */
laai(); teken();
if(navigator.storage && navigator.storage.persist) navigator.storage.persist(); // vra iOS om nie die data uit te vee nie
